import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
		Scanner sc = new Scanner(System.in);
		int t = sc.nextInt();
		int tmp = t;
		int[] n = new int[t];
		int[][] a = new int[t][];
		int max = 0;
		long mod = 998244353L;
		
		for(int i = 0; i<t; i++){
		    n[i] = sc.nextInt();
		    max = Math.max(max, n[i]);
		    a[i] = new int[n[i]];
		    
		    for(int j = 0; j<n[i]; j++) a[i][j] = sc.nextInt();
		}
		
		long[] inv = new long[max+1];
		long[] h = new long[max+1];
		
		if(max>0){
		    inv[1] = 1;
		    for(int i = 2; i<=max; i++){
		        inv[i] = mod - (mod/i) * inv[(int)(mod%i)] %mod;
		    }
		    for(int i = 1; i<max; i++){
		        h[i] = (h[i-1] + inv[i]) % mod;
		    }
		}
		int x = 0;
		while(x<t){
		    int k = x;
		    long ans = 0;
		    for(int i = 0; i<n[k]; i++){
		        long c = (h[i] + h[n[k] - i-1]) % mod;
		        ans = (ans + (long)a[k][i] * c) % mod;
		    }
		    System.out.println(ans);
		    x++;
		}
	}
}
